  let liveDealsData = [...BULK_BLOCK_DEALS];

  function formatIndianCurrency(num) {
    if (num == null || isNaN(num)) return "0.00";
    return Number(num).toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  function formatIndianQty(num) {
    if (num == null || isNaN(num)) return "0";
    return Number(num).toLocaleString("en-IN");
  }

  function parseDealDate(str) {
    if (!str) return null;
    const months = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };
    const parts = String(str).trim().split(/[-/ ]/);
    if (parts.length === 3) {
      let d = parseInt(parts[0], 10);
      let m = months[parts[1].toLowerCase().slice(0, 3)];
      let y = parseInt(parts[2], 10);
      if (y < 100) y += 2000;
      if (!isNaN(d) && m !== undefined && !isNaN(y)) {
        return new Date(y, m, d);
      }
    }
    const fallback = new Date(str);
    return isNaN(fallback.getTime()) ? null : fallback;
  }

  const DealsLiveService = {
    syncDeals: async function () {
      const syncBtn = document.getElementById("deals-sync-btn");
      if (syncBtn) {
        syncBtn.disabled = true;
        syncBtn.innerHTML = '🔄 Syncing Deals...';
      }
      try {
        const base = getApiBase();
        let synced = false;
        if (base) {
          const res = await fetch(`${base}/api/deals`);
          const cType = res.headers.get("content-type") || "";
          if (res.ok && cType.includes("json")) {
            const data = await res.json();
            if (data && Array.isArray(data.deals) && data.deals.length > 0) {
              liveDealsData = data.deals;
              synced = true;
            }
          }
        }
        const updatedEl = document.getElementById("deals-last-updated");
        if (updatedEl) {
          const now = new Date();
          updatedEl.textContent = `Updated ${now.toLocaleTimeString("en-IN", { hour: '2-digit', minute: '2-digit', second: '2-digit' })}`;
        }
        if (State.view === "deals") {
          renderDealsContent();
        }
        showToast(`Synced ${liveDealsData.length} Bulk, Block & Insider deals`, "🤝");
      } catch (err) {
        console.warn("DealsLiveService sync notice:", err);
      } finally {
        if (syncBtn) {
          syncBtn.disabled = false;
          syncBtn.innerHTML = '🔄 Sync Deals';
        }
      }
    }
  };

  function getUniqueStocksInDeals() {
    const stockMap = new Map();
    liveDealsData.forEach(d => {
      const key = d.stock || d.symbol;
      if (!key) return;
      if (!stockMap.has(key)) {
        stockMap.set(key, {
          stock: d.stock,
          symbol: d.symbol,
          count: 0,
          totalValueCr: 0,
          buyCount: 0,
          sellCount: 0
        });
      }
      const item = stockMap.get(key);
      item.count++;
      item.totalValueCr += (d.valueCr || 0);
      if ((d.action || "").toLowerCase() === "buy") item.buyCount++;
      else item.sellCount++;
    });
    return Array.from(stockMap.values()).sort((a, b) => b.totalValueCr - a.totalValueCr);
  }

  function getFilteredDeals() {
    let list = [...liveDealsData];

    // Selected Stock Filter
    if (State.dealsSelectedStock && State.dealsSelectedStock !== "all") {
      const sel = State.dealsSelectedStock.toLowerCase().trim();
      list = list.filter(d =>
        (d.stock && d.stock.toLowerCase() === sel) ||
        (d.symbol && d.symbol.toLowerCase() === sel) ||
        (d.stock && d.stock.toLowerCase().includes(sel))
      );
    }

    // Action filter (all, buy, sell)
    if (State.dealsActionFilter && State.dealsActionFilter !== "all") {
      list = list.filter(d => d.action.toLowerCase() === State.dealsActionFilter.toLowerCase());
    }

    // Type filter (all, Block, Bulk, Insider)
    if (State.dealsTypeFilter && State.dealsTypeFilter !== "all") {
      list = list.filter(d => (d.type || "").toLowerCase() === State.dealsTypeFilter.toLowerCase());
    }

    // Min deal size filter (Cr)
    if (State.dealsMinSize && State.dealsMinSize > 0) {
      list = list.filter(d => (d.valueCr || 0) >= State.dealsMinSize);
    }

    // Duration filter (all, today, yesterday, week, month)
    if (State.dealsDuration && State.dealsDuration !== "all") {
      const uniqueDates = [...new Set(liveDealsData.map(d => d.date))];
      const latestDateStr = uniqueDates[0] || "";
      const ONE_DAY = 24 * 60 * 60 * 1000;

      if (State.dealsDuration === "today") {
        if (latestDateStr) list = list.filter(d => d.date === latestDateStr);
      } else if (State.dealsDuration === "yesterday") {
        const prevDateStr = uniqueDates.length > 1 ? uniqueDates[1] : latestDateStr;
        if (prevDateStr) list = list.filter(d => d.date === prevDateStr);
      } else if (State.dealsDuration === "week") {
        const parsedLatest = parseDealDate(latestDateStr);
        const latestTime = parsedLatest ? parsedLatest.getTime() : Date.now();
        list = list.filter(d => {
          const dt = parseDealDate(d.date);
          return dt ? (latestTime - dt.getTime() <= 7 * ONE_DAY) : true;
        });
      } else if (State.dealsDuration === "month") {
        const parsedLatest = parseDealDate(latestDateStr);
        const latestTime = parsedLatest ? parsedLatest.getTime() : Date.now();
        list = list.filter(d => {
          const dt = parseDealDate(d.date);
          return dt ? (latestTime - dt.getTime() <= 31 * ONE_DAY) : true;
        });
      }
    }

    // Search query filter (stock, symbol, client, insiderRole)
    if (State.dealsSearch && State.dealsSearch.trim() !== "") {
      const q = State.dealsSearch.trim().toLowerCase();
      list = list.filter(d =>
        (d.stock && d.stock.toLowerCase().includes(q)) ||
        (d.symbol && d.symbol.toLowerCase().includes(q)) ||
        (d.client && d.client.toLowerCase().includes(q)) ||
        (d.insiderRole && d.insiderRole.toLowerCase().includes(q))
      );
    }

    return list;
  }

  function renderDealsHighlightCards() {
    let cardsData = [...liveDealsData];

    // If a stock is selected, highlight cards focus on that stock
    if (State.dealsSelectedStock && State.dealsSelectedStock !== "all") {
      const sel = State.dealsSelectedStock.toLowerCase().trim();
      cardsData = cardsData.filter(d =>
        (d.stock && d.stock.toLowerCase() === sel) ||
        (d.symbol && d.symbol.toLowerCase() === sel) ||
        (d.stock && d.stock.toLowerCase().includes(sel))
      );
    } else if (State.dealsSearch && State.dealsSearch.trim() !== "") {
      const q = State.dealsSearch.trim().toLowerCase();
      cardsData = cardsData.filter(d =>
        (d.stock && d.stock.toLowerCase().includes(q)) ||
        (d.symbol && d.symbol.toLowerCase().includes(q))
      );
    }

    if (State.dealsActionFilter && State.dealsActionFilter !== "all") {
      cardsData = cardsData.filter(d => d.action.toLowerCase() === State.dealsActionFilter.toLowerCase());
    }
    if (State.dealsTypeFilter && State.dealsTypeFilter !== "all") {
      cardsData = cardsData.filter(d => (d.type || "").toLowerCase() === State.dealsTypeFilter.toLowerCase());
    }
    // Sort highest deal value first for highlight carousel
    cardsData.sort((a, b) => b.valueCr - a.valueCr);
    const topDeals = cardsData.slice(0, 10);

    if (topDeals.length === 0) {
      return `<div style="padding:16px;color:var(--mu);font-size:13px;">No highlight deals match current filter.</div>`;
    }

    return topDeals.map(d => {
      const actionClass = (d.action || "buy").toLowerCase() === "buy" ? "buy" : "sell";
      const typeClass = (d.type || "bulk").toLowerCase();
      return `
        <div class="deals-highlight-card" data-action="deal-card-click" data-symbol="${d.symbol}" title="Click to view chart for ${d.stock}">
          <div class="deals-card-top">
            <div class="deals-card-brand">
              <div class="deals-card-avatar">${d.avatar || d.stock.charAt(0)}</div>
              <div class="deals-card-stock-name">${d.stock}</div>
            </div>
            <div style="display:flex;align-items:center;gap:4px;">
              <span class="deal-type-badge ${typeClass}" style="margin:0;font-size:9.5px;padding:2px 5px;">${d.type}</span>
              <span class="deal-badge-pill ${actionClass}">${d.action}</span>
            </div>
          </div>
          <div class="deals-card-size-label">Deal Size</div>
          <div class="deals-card-size-val">₹${formatIndianCurrency(d.valueCr)} Cr</div>
          <div class="deals-card-client" title="${d.client}">${d.type === 'Insider' ? '👤 ' : ''}by ${d.client}</div>
        </div>
      `;
    }).join("");
  }

  function renderDealsTableRows() {
    const deals = getFilteredDeals();

    if (deals.length === 0) {
      return `
        <tr>
          <td colspan="7" style="text-align:center;padding:36px;color:var(--mu);">
            <div style="font-size:24px;margin-bottom:8px;">🔍</div>
            <div style="font-weight:600;">No bulk, block, or insider deals found matching your criteria.</div>
            <div style="font-size:12px;margin-top:4px;">Try selecting "Duration: All Dates" or "All Deal Types".</div>
          </td>
        </tr>
      `;
    }

    return deals.map(d => {
      const actionClass = (d.action || "buy").toLowerCase() === "buy" ? "buy" : "sell";
      const typeClass = (d.type || "bulk").toLowerCase();
      const isInsider = typeClass === "insider";
      return `
        <tr class="deals-table-row" data-action="deal-row-click" data-symbol="${d.symbol}" style="cursor:pointer;" title="Click row to open chart for ${d.stock}">
          <td>
            <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
              <span style="font-weight:700;color:var(--ink);">${d.stock}</span>
              <span class="deal-type-badge ${typeClass}">${d.type}</span>
              <button class="deal-stock-filter-btn" data-action="filter-deal-stock" data-stock="${d.stock}" title="Filter all deals for ${d.stock}" style="background:rgba(255,255,255,0.05);border:1px solid var(--ln);border-radius:4px;color:var(--mu);padding:2px 6px;font-size:10px;cursor:pointer;display:inline-flex;align-items:center;gap:3px;margin-left:auto;transition:all 0.15s;">
                🔍 Filter
              </button>
            </div>
          </td>
          <td style="color:var(--mu);white-space:nowrap;font-weight:600;">${d.date}</td>
          <td style="color:var(--ink);max-width:320px;white-space:normal;" title="${d.client}">
            <div>
              <span style="font-weight:600;">${d.client}</span>
              ${isInsider ? `<span class="insider-role-pill" title="${d.mode || 'SEBI PIT Continual Disclosure'}">${d.insiderRole || d.clientCategory || 'Insider'}</span>` : ''}
            </div>
            ${isInsider && (d.mode || d.postHoldingPct) ? `
              <div style="font-size:11px;color:var(--mu);margin-top:2px;display:flex;gap:6px;align-items:center;">
                ${d.mode ? `<span>${d.mode}</span>` : ''}
                ${d.postHoldingPct ? `<span>• Post Stake: <strong style="color:var(--ink);">${d.postHoldingPct}</strong></span>` : ''}
              </div>
            ` : ''}
          </td>
          <td>
            <span class="deal-action-text ${actionClass}">${d.action}</span>
          </td>
          <td style="text-align:right;font-family:var(--font-mono);font-weight:600;color:var(--ink);">
            ${formatIndianQty(d.qty)}
          </td>
          <td style="text-align:right;font-family:var(--font-mono);color:var(--ink);">
            ${formatIndianCurrency(d.avgPrice)}
          </td>
          <td style="text-align:right;font-family:var(--font-mono);font-weight:800;color:var(--ink);">
            ${formatIndianCurrency(d.valueCr)}
          </td>
        </tr>
      `;
    }).join("");
  }

  function renderDealsQuickChipsHtml() {
    const uniqueStocks = getUniqueStocksInDeals();
    const activeStock = (State.dealsSelectedStock && State.dealsSelectedStock !== "all") ? State.dealsSelectedStock : "";
    const searchVal = (State.dealsSearch || "").trim().toLowerCase();

    return `
      <span style="font-size:11px;font-weight:700;color:var(--mu);text-transform:uppercase;letter-spacing:0.5px;white-space:nowrap;margin-right:2px;">⚡ Active:</span>
      <button class="deals-stock-chip ${!activeStock && !searchVal ? 'active' : ''}" data-deals-stock-chip="all">
        All Stocks (${liveDealsData.length})
      </button>
      ${uniqueStocks.slice(0, 14).map(s => {
      const isSelected = (activeStock && activeStock.toLowerCase() === s.stock.toLowerCase()) ||
        (searchVal && searchVal === s.stock.toLowerCase());
      return `
          <button class="deals-stock-chip ${isSelected ? 'active' : ''}" data-deals-stock-chip="${s.stock}" title="${s.stock} (${s.count} deals · ₹${formatIndianCurrency(s.totalValueCr)} Cr)">
            <span>${s.stock}</span>
            <span style="font-size:10px;padding:1px 5px;border-radius:8px;background:rgba(255,255,255,0.08);color:${isSelected ? 'var(--g)' : 'var(--mu)'};">${s.count}</span>
          </button>
        `;
    }).join('')}
    `;
  }

  function renderDealsStockSelectOptionsHtml() {
    const uniqueStocks = getUniqueStocksInDeals();
    const activeStock = (State.dealsSelectedStock && State.dealsSelectedStock !== "all") ? State.dealsSelectedStock : "";

    return `
      <option value="all" ${!activeStock ? 'selected' : ''}>🔍 All Companies (${uniqueStocks.length})</option>
      ${uniqueStocks.map(s => `
        <option value="${s.stock}" ${(activeStock && activeStock.toLowerCase() === s.stock.toLowerCase()) ? 'selected' : ''}>${s.stock} (${s.count} deals · ₹${formatIndianCurrency(s.totalValueCr)} Cr)</option>
      `).join('')}
    `;
  }

  function renderDealsStockSearchPanel() {
    const uniqueStocks = getUniqueStocksInDeals();
    const activeStock = (State.dealsSelectedStock && State.dealsSelectedStock !== "all") ? State.dealsSelectedStock : (State.dealsSearch ? State.dealsSearch.trim() : "");
    const filteredDeals = getFilteredDeals();

    return `
      <div class="deals-stock-search-panel" id="deals-stock-search-panel">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;">
          <div style="display:flex;align-items:center;gap:8px;">
            <span style="font-size:16px;">🔎</span>
            <span style="font-size:14px;font-weight:700;color:var(--ink);letter-spacing:0.2px;">Search Particular Stock</span>
            <span class="nav-badge-pill" id="deals-companies-count" style="font-size:11px;background:rgba(255,255,255,0.06);color:var(--mu);">${uniqueStocks.length} Companies in Feed</span>
          </div>
          ${activeStock ? `
            <button id="deals-clear-all-stock-filter-btn" class="row-action-btn" style="padding:4px 12px;font-size:12px;color:var(--r);border-color:rgba(239,68,68,0.3);background:rgba(239,68,68,0.08);cursor:pointer;border-radius:var(--radius-sm);display:inline-flex;align-items:center;gap:5px;">
              <span>✕</span> <span>Reset Stock Filter</span>
            </button>
          ` : ''}
        </div>

        <!-- Search Input with Live Autocomplete Suggestions -->
        <div class="deals-search-input-wrap">
          <span style="color:var(--mu);font-size:15px;">🔍</span>
          <input 
            type="text" 
            id="deals-stock-search-input" 
            placeholder="Search stock name or symbol (e.g. Kaynes, Marsons, MV Electro, BLS, Baazar)..." 
            value="${activeStock}"
            autocomplete="off"
            spellcheck="false"
          >
          ${activeStock ? `
            <button id="deals-search-clear-icon" style="background:transparent;border:none;color:var(--mu);cursor:pointer;padding:4px 6px;font-size:14px;display:flex;align-items:center;" title="Clear search">✕</button>
          ` : ''}
          
          <!-- Dropdown suggestions popover panel -->
          <div id="deals-stock-suggestions" class="deals-stock-suggestions" style="display:none;"></div>
        </div>

        <!-- Quick Pick Stock Chips (Top active companies with deal counts) -->
        <div class="deals-quick-chips-scroll" id="deals-quick-chips-scroll">
          ${renderDealsQuickChipsHtml()}
        </div>

        <!-- Active Stock Filter Indicator Banner Container -->
        <div id="deals-active-filter-banner-wrap">
          ${activeStock ? `
            <div id="deals-active-filter-banner" style="background:rgba(34,197,94,0.08);border:1px solid rgba(34,197,94,0.3);border-radius:var(--radius-sm);padding:8px 14px;display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12.5px;">
              <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
                <span style="color:var(--g);font-weight:700;display:inline-flex;align-items:center;gap:5px;">
                  <span>🎯</span> <span>Active Stock:</span>
                </span>
                <span style="font-weight:700;color:var(--ink);">${activeStock}</span>
                <span style="color:var(--mu);font-size:12px;">• ${filteredDeals.length} bulk/block deals matching</span>
              </div>
              <button id="deals-reset-banner-btn" style="background:none;border:none;color:var(--g);cursor:pointer;text-decoration:underline;font-size:12px;font-weight:600;">
                Show All Stocks
              </button>
            </div>
          ` : ''}
        </div>
      </div>
    `;
  }

  function renderDealsContent() {
    const cardsScroll = document.getElementById("deals-cards-scroll");
    if (cardsScroll) {
      cardsScroll.innerHTML = renderDealsHighlightCards();
    }
    const tableBody = document.getElementById("deals-table-body");
    if (tableBody) {
      tableBody.innerHTML = renderDealsTableRows();
    }
    const countBadge = document.getElementById("deals-count-badge");
    if (countBadge) {
      countBadge.textContent = `${getFilteredDeals().length} Deals`;
    }

    // Update Quick Chips Scroll
    const chipsWrap = document.getElementById("deals-quick-chips-scroll");
    if (chipsWrap) {
      chipsWrap.innerHTML = renderDealsQuickChipsHtml();
    }

    // Update Stock Select Dropdown
    const stockSelect = document.getElementById("deals-stock-select");
    if (stockSelect) {
      stockSelect.innerHTML = renderDealsStockSelectOptionsHtml();
    }

    // Update Companies Count in Header
    const compCount = document.getElementById("deals-companies-count");
    if (compCount) {
      compCount.textContent = `${getUniqueStocksInDeals().length} Companies in Feed`;
    }

    // Update Active Filter Banner
    const bannerContainer = document.getElementById("deals-active-filter-banner-wrap");
    if (bannerContainer) {
      const activeStock = (State.dealsSelectedStock && State.dealsSelectedStock !== "all") ? State.dealsSelectedStock : (State.dealsSearch ? State.dealsSearch.trim() : "");
      if (activeStock) {
        const count = getFilteredDeals().length;
        bannerContainer.innerHTML = `
          <div id="deals-active-filter-banner" style="background:rgba(34,197,94,0.08);border:1px solid rgba(34,197,94,0.3);border-radius:var(--radius-sm);padding:8px 14px;display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12.5px;">
            <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
              <span style="color:var(--g);font-weight:700;display:inline-flex;align-items:center;gap:5px;">
                <span>🎯</span> <span>Active Stock:</span>
              </span>
              <span style="font-weight:700;color:var(--ink);">${activeStock}</span>
              <span style="color:var(--mu);font-size:12px;">• ${count} deals matching</span>
            </div>
            <button id="deals-reset-banner-btn" style="background:none;border:none;color:var(--g);cursor:pointer;text-decoration:underline;font-size:12px;font-weight:600;">
              Show All Stocks
            </button>
          </div>
        `;
      } else {
        bannerContainer.innerHTML = "";
      }
    }
  }

  function renderOrderFlowView() {
    return `
      <div class="orderflow-view-wrapper" style="display:flex;flex-direction:column;height:calc(100vh - 54px);margin:-16px -24px -24px -24px;background:#0d1117;">
        <!-- Order Flow Top Toolbar -->
        <div class="orderflow-nav-toolbar" style="display:flex;align-items:center;justify-content:space-between;padding:10px 18px;background:var(--sf);border-bottom:1px solid var(--ln);flex-wrap:wrap;gap:10px;">
          <div style="display:flex;align-items:center;gap:12px;">
            <button class="section-back-btn" data-action="go-back" title="Back to previous page" style="background:var(--sf2);border:1px solid var(--ln);color:var(--ink);padding:4px 10px;border-radius:6px;cursor:pointer;font-size:12px;display:inline-flex;align-items:center;gap:4px;">
              <span class="back-arrow">←</span> <span>Back</span>
            </button>
            <div style="display:flex;align-items:center;gap:8px;">
              <span style="font-size:15px;font-weight:700;color:var(--ink);letter-spacing:-0.2px;display:flex;align-items:center;gap:6px;">
                🌪️ F&O Order Flow
              </span>
              <span style="background:rgba(34,197,94,0.16);color:#22c55e;font-size:11px;font-weight:600;padding:2px 7px;border-radius:4px;border:1px solid rgba(34,197,94,0.3);">
                LIVE F&O
              </span>
              <span style="font-size:12px;color:var(--mu);display:inline-block;" class="hide-mobile">
                • 217 NSE & BSE Underlyings · Futures Money Flow · Strike OI Distribution · Sentiment & Conviction
              </span>
            </div>
          </div>
          <div style="display:flex;align-items:center;gap:10px;">
            <button id="orderflow-refresh-btn" onclick="const iframe=document.getElementById('orderflow-iframe'); if (iframe) iframe.src = iframe.src;" style="display:inline-flex;align-items:center;gap:5px;background:var(--sf2);border:1px solid var(--ln);color:var(--ink);padding:5px 12px;border-radius:6px;cursor:pointer;font-size:12px;font-weight:500;transition:all 0.15s ease;" title="Reload Order Flow Board">
              <span>↻ Reload</span>
            </button>
            <a href="/order-flow/" target="_blank" rel="noopener noreferrer" style="display:inline-flex;align-items:center;gap:5px;background:var(--g);border:1px solid var(--g);color:#050d08;font-weight:700;padding:5px 14px;border-radius:6px;text-decoration:none;font-size:12px;box-shadow:0 0 12px rgba(34,197,94,0.35);transition:opacity 0.15s ease;" title="Open Order Flow in Standalone Fullscreen Tab">
              <span>Fullscreen Tab ↗</span>
            </a>
          </div>
        </div>

        <!-- Embedded Order Flow React Application Frame -->
        <div style="flex:1;width:100%;height:100%;position:relative;background:#0d1117;overflow:hidden;">
          <iframe id="orderflow-iframe" src="/order-flow/?v=6.0.5" style="width:100%;height:100%;border:none;display:block;" title="F&O Order Flow"></iframe>
        </div>
      </div>
    `;
  }

  function renderDealsView() {
    const deals = getFilteredDeals();
    const uniqueDates = [...new Set(liveDealsData.map(d => d.date))];
    const latestDateStr = uniqueDates[0] || "Today";
    const prevDateStr = uniqueDates.length > 1 ? uniqueDates[1] : "";

    const typeCounts = {
      all: liveDealsData.length,
      bulk: liveDealsData.filter(d => (d.type || "").toLowerCase() === "bulk").length,
      block: liveDealsData.filter(d => (d.type || "").toLowerCase() === "block").length,
      insider: liveDealsData.filter(d => (d.type || "").toLowerCase() === "insider").length
    };

    return `
      <div class="deals-container">
        <!-- Header Bar -->
        <div class="view-header-bar" style="display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:4px 0 16px 0;border-bottom:1px solid var(--ln);">
          <div class="view-title-left" style="display:flex;align-items:center;gap:12px;">
            <button class="section-back-btn" data-action="go-back" title="Back to previous page">
              <span class="back-arrow">←</span> <span>Back</span>
            </button>
            <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
              <h2 style="font-size:20px;font-weight:700;color:var(--ink);margin:0;display:flex;align-items:center;gap:6px;">
                Bulk, Block & Insider Deals <span style="font-size:14px;color:var(--mu);cursor:help;" title="Direct institutional NSE & BSE Bulk / Block transactions and SEBI PIT Insider Trading disclosures">ⓘ</span>
              </h2>
              <span class="nav-badge-pill" style="background:rgba(34,197,94,0.15);color:#22c55e;font-weight:700;display:inline-flex;align-items:center;gap:5px;">
                <span class="live-pulse" style="width:6px;height:6px;border-radius:50%;background:#22c55e;display:inline-block;"></span>
                Live Deals & Insider Feed
              </span>
              <span id="deals-count-badge" class="nav-badge-pill">${deals.length} Deals</span>
              <span id="deals-last-updated" style="font-size:12px;color:var(--mu);">Live</span>
            </div>
          </div>
          <div style="display:flex;align-items:center;gap:10px;">
            <button id="deals-sync-btn" class="row-action-btn" style="padding:7px 14px;font-weight:700;font-size:12px;cursor:pointer;border-radius:var(--radius-sm);display:inline-flex;align-items:center;gap:6px;">
              🔄 Sync Deals
            </button>
            <button id="deals-export-btn" class="row-action-btn" style="padding:7px 14px;border-color:var(--g);color:var(--g);font-weight:700;font-size:12px;cursor:pointer;border-radius:var(--radius-sm);display:inline-flex;align-items:center;gap:6px;">
              📥 Export CSV
            </button>
          </div>
        </div>

        <!-- Top Highlight Cards (Matching Exact Screenshot) -->
        <div class="deals-cards-scroll-wrap" id="deals-cards-scroll">
          ${renderDealsHighlightCards()}
        </div>

        <!-- Dedicated Stock Search Panel -->
        ${renderDealsStockSearchPanel()}

        <!-- Filter Controls Toolbar -->
        <div class="deals-filter-toolbar">
          <div class="deals-filter-left">
            <!-- Action Segmented Filter (All, Buy, Sell) -->
            <div class="pill-segmented-control">
              <button class="pill-segment-btn ${State.dealsActionFilter === 'all' ? 'active' : ''}" data-deals-action="all">All</button>
              <button class="pill-segment-btn ${State.dealsActionFilter === 'buy' ? 'active' : ''}" data-deals-action="buy">Buy</button>
              <button class="pill-segment-btn ${State.dealsActionFilter === 'sell' ? 'active' : ''}" data-deals-action="sell">Sell</button>
            </div>

            <!-- Stock Dropdown Selector -->
            <select class="screener-select" id="deals-stock-select" style="min-width:170px;max-width:240px;">
              ${renderDealsStockSelectOptionsHtml()}
            </select>

            <!-- Deal Type Dropdown (Bulk, Block, Insider) -->
            <select class="screener-select" id="deals-type-select" style="min-width:140px;">
              <option value="all" ${State.dealsTypeFilter === 'all' ? 'selected' : ''}>All Deal Types (${typeCounts.all})</option>
              <option value="Bulk" ${State.dealsTypeFilter === 'Bulk' ? 'selected' : ''}>Bulk Deals (${typeCounts.bulk})</option>
              <option value="Block" ${State.dealsTypeFilter === 'Block' ? 'selected' : ''}>Block Deals (${typeCounts.block})</option>
              <option value="Insider" ${State.dealsTypeFilter === 'Insider' ? 'selected' : ''}>Insider Trades (${typeCounts.insider})</option>
            </select>

            <!-- Min Deal Size Dropdown -->
            <select class="screener-select" id="deals-min-size-select" style="min-width:120px;">
              <option value="0" ${State.dealsMinSize === 0 ? 'selected' : ''}>All Deal Sizes</option>
              <option value="1" ${State.dealsMinSize === 1 ? 'selected' : ''}>> ₹1 Cr</option>
              <option value="5" ${State.dealsMinSize === 5 ? 'selected' : ''}>> ₹5 Cr</option>
              <option value="10" ${State.dealsMinSize === 10 ? 'selected' : ''}>> ₹10 Cr</option>
              <option value="50" ${State.dealsMinSize === 50 ? 'selected' : ''}>> ₹50 Cr</option>
              <option value="100" ${State.dealsMinSize === 100 ? 'selected' : ''}>> ₹100 Cr</option>
              <option value="250" ${State.dealsMinSize === 250 ? 'selected' : ''}>> ₹250 Cr</option>
              <option value="500" ${State.dealsMinSize === 500 ? 'selected' : ''}>> ₹500 Cr</option>
            </select>
          </div>

          <div class="deals-filter-right">
            <!-- Duration Selector supporting All Dates, Latest Session, Prev Session, Last 7 Days, Last 30 Days -->
            <select class="screener-select deals-duration-select" id="deals-duration-select" style="min-width:190px;">
              <option value="all" ${State.dealsDuration === 'all' ? 'selected' : ''}>Duration: All Dates (${uniqueDates.length} Days)</option>
              <option value="today" ${State.dealsDuration === 'today' ? 'selected' : ''}>Duration: Latest (${latestDateStr})</option>
              ${prevDateStr ? `<option value="yesterday" ${State.dealsDuration === 'yesterday' ? 'selected' : ''}>Duration: Previous (${prevDateStr})</option>` : ''}
              <option value="week" ${State.dealsDuration === 'week' ? 'selected' : ''}>Duration: Last 7 Days</option>
              <option value="month" ${State.dealsDuration === 'month' ? 'selected' : ''}>Duration: Last 30 Days</option>
            </select>

            <!-- Client or Keyword Search Input -->
            <div style="display:inline-flex;align-items:center;position:relative;">
              <span style="position:absolute;left:10px;color:var(--mu);font-size:12px;pointer-events:none;display:flex;align-items:center;" aria-hidden="true">🔍</span>
              <input type="text" class="screener-input" id="deals-search-input" placeholder="Search client, insider, role..." value="${State.dealsSearch}" style="padding-left:28px;">
            </div>
          </div>
        </div>

        <!-- Main Deals Table (Exact Columns Matching Screenshot) -->
        <div class="table-card-container table-container" style="margin-top:0">
          <div class="table-scroll-wrapper deals-scroll-wrapper">
            <table class="data-table-main deals-table">
            <thead>
              <tr>
                <th style="padding:12px 16px;">Stock</th>
                <th style="padding:12px 16px;">Date</th>
                <th style="padding:12px 16px;">Client / Insider</th>
                <th style="padding:12px 16px;">Action</th>
                <th style="text-align:right;padding:12px 16px;">Qty</th>
                <th style="text-align:right;padding:12px 16px;">Avg price</th>
                <th style="text-align:right;padding:12px 16px;">Value(Cr)</th>
              </tr>
            </thead>
            <tbody id="deals-table-body">
              ${renderDealsTableRows()}
            </tbody>
          </table>
        </div>
      </div>
    `;
  }

  function setupDealsEvents() {
    // Action Segmented Buttons (All, Buy, Sell)
    document.querySelectorAll("[data-deals-action]").forEach(btn => {
      btn.addEventListener("click", e => {
        e.preventDefault();
        const action = btn.getAttribute("data-deals-action");
        State.dealsActionFilter = action;
        document.querySelectorAll("[data-deals-action]").forEach(b => b.classList.toggle("active", b === btn));
        renderDealsContent();
      });
    });

    // Deal Type Select
    const typeSelect = document.getElementById("deals-type-select");
    if (typeSelect) {
      typeSelect.addEventListener("change", e => {
        State.dealsTypeFilter = e.target.value;
        renderDealsContent();
      });
    }

    // Min Size Select
    const minSizeSelect = document.getElementById("deals-min-size-select");
    if (minSizeSelect) {
      minSizeSelect.addEventListener("change", e => {
        State.dealsMinSize = parseFloat(e.target.value) || 0;
        renderDealsContent();
      });
    }

    // Stock Dropdown Select
    const stockSelect = document.getElementById("deals-stock-select");
    if (stockSelect) {
      stockSelect.addEventListener("change", e => {
        State.dealsSelectedStock = e.target.value;
        State.dealsSearch = "";
        const searchInput = document.getElementById("deals-stock-search-input");
        if (searchInput) searchInput.value = e.target.value === "all" ? "" : e.target.value;
        renderDealsContent();
      });
    }

    // Duration Select
    const durationSelect = document.getElementById("deals-duration-select");
    if (durationSelect) {
      durationSelect.addEventListener("change", e => {
        State.dealsDuration = e.target.value;
        renderDealsContent();
      });
    }

    // Client/Counterparty Search Input
    const searchInput = document.getElementById("deals-search-input");
    if (searchInput) {
      searchInput.addEventListener("input", e => {
        State.dealsSearch = e.target.value;
        renderDealsContent();
      });
    }

    // Stock Search Input & Autocomplete Popover
    const stockSearchInput = document.getElementById("deals-stock-search-input");
    const suggestionsPanel = document.getElementById("deals-stock-suggestions");

    if (stockSearchInput) {
      const showSuggestions = (query) => {
        if (!suggestionsPanel) return;
        const q = (query || "").trim().toLowerCase();
        if (!q) {
          suggestionsPanel.style.display = "none";
          suggestionsPanel.innerHTML = "";
          return;
        }

        const uniqueStocks = getUniqueStocksInDeals();
        const matches = uniqueStocks.filter(s =>
          s.stock.toLowerCase().includes(q) ||
          (s.symbol && s.symbol.toLowerCase().includes(q))
        );

        if (matches.length === 0) {
          suggestionsPanel.innerHTML = `
            <div style="padding:12px 16px;color:var(--mu);font-size:12.5px;text-align:center;">
              No companies in current deals feed match "<strong>${query}</strong>"
            </div>
          `;
          suggestionsPanel.style.display = "block";
          return;
        }

        suggestionsPanel.innerHTML = matches.map(s => `
          <div class="deals-suggestion-item" data-select-stock="${s.stock}">
            <div style="display:flex;align-items:center;gap:10px;min-width:0;">
              <div style="width:28px;height:28px;border-radius:6px;background:var(--sf2);border:1px solid var(--ln);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:12px;color:var(--ink);">
                ${s.stock.charAt(0)}
              </div>
              <div style="min-width:0;">
                <div style="font-weight:700;font-size:13px;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">
                  ${s.stock}
                </div>
                <div style="font-size:11px;color:var(--mu);display:flex;align-items:center;gap:6px;">
                  <span>${s.symbol || ''}</span>
                  <span>•</span>
                  <span>${s.count} Deals</span>
                  ${s.buyCount > 0 ? `<span style="color:var(--g);">Buy: ${s.buyCount}</span>` : ''}
                  ${s.sellCount > 0 ? `<span style="color:var(--r);">Sell: ${s.sellCount}</span>` : ''}
                </div>
              </div>
            </div>
            <div style="text-align:right;white-space:nowrap;">
              <div style="font-size:12px;font-weight:700;color:var(--ink);">₹${formatIndianCurrency(s.totalValueCr)} Cr</div>
              <div style="font-size:10px;color:var(--mu);">Total Value</div>
            </div>
          </div>
        `).join("");
        suggestionsPanel.style.display = "block";
      };

      stockSearchInput.addEventListener("input", e => {
        const val = e.target.value;
        State.dealsSearch = val;
        State.dealsSelectedStock = "all";
        showSuggestions(val);
        renderDealsContent();
      });

      stockSearchInput.addEventListener("focus", () => {
        if (stockSearchInput.value.trim()) {
          showSuggestions(stockSearchInput.value);
        }
      });
    }

    // Click outside closes suggestion popover
    document.addEventListener("click", e => {
      if (!e.target.closest(".deals-search-input-wrap")) {
        const p = document.getElementById("deals-stock-suggestions");
        if (p) p.style.display = "none";
      }

      // Suggestion item selection
      const suggestionItem = e.target.closest("[data-select-stock]");
      if (suggestionItem) {
        const stk = suggestionItem.getAttribute("data-select-stock");
        State.dealsSelectedStock = stk;
        State.dealsSearch = "";
        const input = document.getElementById("deals-stock-search-input");
        if (input) input.value = stk;
        const p = document.getElementById("deals-stock-suggestions");
        if (p) p.style.display = "none";
        renderDealsContent();
        return;
      }

      // Quick Stock Chip click
      const chip = e.target.closest("[data-deals-stock-chip]");
      if (chip) {
        const stk = chip.getAttribute("data-deals-stock-chip");
        State.dealsSelectedStock = stk;
        State.dealsSearch = "";
        const input = document.getElementById("deals-stock-search-input");
        if (input) input.value = stk === "all" ? "" : stk;
        const p = document.getElementById("deals-stock-suggestions");
        if (p) p.style.display = "none";
        renderDealsContent();
        return;
      }

      // Clear / Reset buttons
      if (e.target.closest("#deals-clear-all-stock-filter-btn, #deals-search-clear-icon, #deals-reset-banner-btn")) {
        State.dealsSelectedStock = "all";
        State.dealsSearch = "";
        const input = document.getElementById("deals-stock-search-input");
        if (input) input.value = "";
        const input2 = document.getElementById("deals-search-input");
        if (input2) input2.value = "";
        const sel = document.getElementById("deals-stock-select");
        if (sel) sel.value = "all";
        const p = document.getElementById("deals-stock-suggestions");
        if (p) p.style.display = "none";
        renderDealsContent();
        return;
      }

      // Stock row filter click from table
      const filterBtn = e.target.closest("[data-action='filter-deal-stock']");
      if (filterBtn) {
        e.stopPropagation();
        const stk = filterBtn.getAttribute("data-stock");
        if (stk) {
          State.dealsSelectedStock = stk;
          State.dealsSearch = "";
          const input = document.getElementById("deals-stock-search-input");
          if (input) input.value = stk;
          const p = document.getElementById("deals-stock-suggestions");
          if (p) p.style.display = "none";
          renderDealsContent();
          showToast(`Filtered deals for ${stk}`, "🎯");
        }
        return;
      }
    });

    // Sync Button
    const syncBtn = document.getElementById("deals-sync-btn");
    if (syncBtn) {
      syncBtn.addEventListener("click", () => {
        DealsLiveService.syncDeals();
      });
    }

    // Export CSV
    const exportBtn = document.getElementById("deals-export-btn");
    if (exportBtn) {
      exportBtn.addEventListener("click", () => {
        exportDealsCSV();
      });
    }

    // Deal Click Delegation (Cards and Rows)
    const container = document.querySelector(".deals-container");
    if (container) {
      container.addEventListener("click", e => {
        // If clicking filter button, don't trigger chart navigation
        if (e.target.closest("[data-action='filter-deal-stock']")) return;

        const target = e.target.closest("[data-action='deal-card-click'], [data-action='deal-row-click']");
        if (target) {
          const sym = target.getAttribute("data-symbol");
          if (sym) {
            if (State.view !== "stock" && State.view !== "login") State.previousView = State.view;
            State.activeStock = sym;
            State.view = "stock";
            window.location.hash = "stock";
            renderActiveView();
            window.scrollTo({ top: 0, behavior: "smooth" });
          }
        }
      });
    }
  }

  function exportDealsCSV() {
    const deals = getFilteredDeals();
    if (!deals || deals.length === 0) {
      showToast("No deals available to export", "⚠️");
      return;
    }
    const headers = ["Stock", "Symbol", "Type", "Date", "Client", "Role / Category", "Action", "Qty", "Avg Price (INR)", "Value (Cr)", "Mode / Remarks"];
    const rows = deals.map(d => [
      `"${(d.stock || "").replace(/"/g, '""')}"`,
      `"${d.symbol || ""}"`,
      `"${d.type || ""}"`,
      `"${d.date || ""}"`,
      `"${(d.client || "").replace(/"/g, '""')}"`,
      `"${(d.insiderRole || d.clientCategory || "").replace(/"/g, '""')}"`,
      `"${d.action || ""}"`,
      d.qty || 0,
      d.avgPrice || 0,
      d.valueCr || 0,
      `"${(d.mode || "").replace(/"/g, '""')}"`
    ]);

    const csvContent = [headers.join(","), ...rows.map(r => r.join(","))].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `Bulk_Block_Insider_Deals_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast(`Exported ${deals.length} deals to CSV`, "📥");
  }

